Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1000111;
const long long MOD = 1000000007;

long long visited[MAXN], freqCount[MAXN];

long long powerMod(long long base, int exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    int p, k;
    cin >> p >> k;
    if (k == 0) {
        cout << powerMod(p, p - 1) << endl;
        return 0;
    }
    if (k == 1) {
        cout << powerMod(p, p) << endl;
        return 0;
    }
    fill(visited, visited + p, 0);
    fill(freqCount, freqCount + p, 0);
    for (int start = 1; start < p; start++) {
        if (visited[start]) continue;
        long long u = start, cycleLength = 0;
        while (!visited[u]) {
            visited[u] = 1;
            u = (u * k) % p;
            cycleLength++;
        }
        freqCount[cycleLength]++;
    }
    long long result = 1;
    for (int length = 1; length <= p - 1; length++) {
        if (freqCount[length] == 0) continue;
        long long tmp = powerMod((length * freqCount[length] + 1) % MOD, freqCount[length]);
        result = (result * tmp) % MOD;
    }
    cout << result << endl;
    return 0;
}
</original_code>
